            return $this->nestedControlStructureStatementEnd($tokens, $nextIndex, $nextToken);
        }

        return $this->scanControlStructureStatementEnd($tokens, $parenthesisEndIndex);
    }

    /**
     * @return list<int>
     */
    public function controlStructureTokenKinds(): array
    {
        $this->controlStructureTrail[] = $this->controlStructureIndex;
        return $this->isControlStructureOpeningKind(0, true);
    }

    private function resetAlternativeSyntaxScan(Tokens $tokens, int $index): void
    {
