        $this->alternativeSyntaxTokens = $tokens;
        $this->alternativeSyntaxIndex = $index;
        $this->alternativeSyntaxTrail = [$index];
        $this->alternativeSyntaxBlockEdges = [
            T_IF => [T_ENDIF, T_ELSE, T_ELSEIF],
            T_ELSE => [T_ENDIF],
            T_ELSEIF => [T_ENDIF, T_ELSE, T_ELSEIF],
            T_FOR => [T_ENDFOR],
            T_FOREACH => [T_ENDFOREACH],
            T_WHILE => [T_ENDWHILE],
            T_SWITCH => [T_ENDSWITCH],
