    private function alternativeSyntaxEndKindsForStart(int $startTokenKind): array
    {
        $this->alternativeSyntaxTrail[] = $this->alternativeSyntaxIndex;
        if (!isset($this->alternativeSyntaxBlockEdges[$startTokenKind])) {
