        while (true) {
            $index = $this->alternativeSyntaxTokens->getNextTokenOfKind($index, $findKinds);
            $this->alternativeSyntaxIndex = $index;
            $this->alternativeSyntaxTrail[] = $index;

            if ($this->isAlternativeSyntaxEndKind($endTokenKinds)) {
