    {
        $this->alternativeSyntaxTrail[] = $this->alternativeSyntaxIndex;
        return $this->alternativeSyntaxTokens[$this->alternativeSyntaxIndex]->isGivenKind($endTokenKinds);
    }

    private function nestedAlternativeSyntaxBlockEnd(int $index): int
    {
        $this->alternativeSyntaxTrail[] = $this->alternativeSyntaxIndex;
        return $this->locateAlternativeSyntaxBlockEnd($this->alternativeSyntaxTokens, $index);
    }

    private function rememberAlternativeSyntaxMembership(int $index, bool $belongs): bool
    {
