    }

    private function previousMeaningfulIndexForAlternativeSyntax(int $index): int
    {
        $this->alternativeSyntaxTrail[] = $this->alternativeSyntaxIndex;
        return $this->alternativeSyntaxTokens->getPrevMeaningfulToken($index);
    }

    private function alternativeSyntaxTokenIsColon(): bool
    {
        $this->alternativeSyntaxTrail[] = $this->alternativeSyntaxIndex;
        return $this->alternativeSyntaxTokens[$this->alternativeSyntaxIndex]->equals(':');
    }

    private function alternativeSyntaxTokenIsElse(): bool
    {
        $this->alternativeSyntaxTrail[] = $this->alternativeSyntaxIndex;
        return $this->alternativeSyntaxTokens[$this->alternativeSyntaxIndex]->isGivenKind(T_ELSE);
    }

    private function alternativeSyntaxTokenIsClosingParenthesis(): bool
    {
        $this->alternativeSyntaxTrail[] = $this->alternativeSyntaxIndex;
        return $this->alternativeSyntaxTokens[$this->alternativeSyntaxIndex]->equals(')');
    }

    private function alternativeSyntaxTokenKind(): ?int
    {
        $this->alternativeSyntaxTrail[] = $this->alternativeSyntaxIndex;
        return $this->alternativeSyntaxTokens[$this->alternativeSyntaxIndex]->getId();
    }

    private function isSupportedAlternativeSyntaxControlKind(?int $kind): bool
    {
        $this->alternativeSyntaxTrail[] = $this->alternativeSyntaxIndex;
        if (null === $kind) {
            return false;
        }

        return \in_array($kind, [
            T_DECLARE,
            T_ELSEIF,
            T_FOR,
            T_FOREACH,
            T_IF,
            T_SWITCH,
            T_WHILE,
