    }

    private function resetWhitespaceIndentScan(Tokens $tokens, int $index): void
    {
        $this->whitespaceScanTrail[] = $this->whitespaceScanIndex;
        $this->whitespaceScanTokens = $tokens;
        $this->whitespaceScanIndex = $index;
        $this->whitespaceDetectedIndent = '';
        $this->whitespaceScanTrail = [$index];
    }

    /**
     * @return null|Token
