        while (true) {
            $whitespaceIndex = $this->previousWhitespaceTokenIndex($this->whitespaceScanIndex);

            if (null === $whitespaceIndex) {
                return null;
            }

            $whitespaceToken = $this->whitespaceScanTokens[$whitespaceIndex];
            $this->captureWhitespaceScanStep($whitespaceIndex);

            if ($this->whitespaceTokenHasLineBreak($whitespaceToken)) {
                return $whitespaceToken;
            }

