    private function previousWhitespaceTokenIndex(int $index): ?int
    {
        $this->whitespaceScanTrail[] = $this->whitespaceScanIndex;
        return $this->whitespaceScanTokens->getPrevTokenOfKind($index, [[T_WHITESPACE]]);
    }

    private function whitespaceTokenHasLineBreak(Token $whitespaceToken): bool
    {
        $this->whitespaceScanTrail[] = $this->whitespaceScanIndex;
        return str_contains($whitespaceToken->getContent(), "\n");
    }

    private function openTagOrCommentEndsWithNewline(int $whitespaceIndex): bool
    {
