        $prevToken = $this->whitespaceScanTokens[$whitespaceIndex - 1];

        if (!$this->isOpenTagTokenForWhitespaceScan($prevToken) && !$this->isCommentTokenForWhitespaceScan($prevToken)) {
            return false;
        }

        return $this->whitespaceContentEndsWithNewline($prevToken->getContent());
    }

    private function extractIndentFromWhitespaceToken(Token $whitespaceToken): string
    {
