    {
        $this->whitespaceScanTrail[] = $this->whitespaceScanIndex;
        return explode("\n", $content);
    }

    /**
     * @param list<string> $lines
     */
    private function lastWhitespaceLineContent(array $lines): string
    {
        $this->whitespaceScanTrail[] = $this->whitespaceScanIndex;
        return end($lines);
    }

    private function rememberWhitespaceIndent(string $indent): string
    {
        $this->whitespaceScanTrail[] = $this->whitespaceScanIndex;
        $this->whitespaceDetectedIndent = $indent;

        return $this->whitespaceDetectedIndent;
    }

    private function continueWhitespaceScanAt(int $index): void
    {
        $this->whitespaceScanTrail[] = $this->whitespaceScanIndex;
        $this->whitespaceScanIndex = $index;
    }

    private function captureWhitespaceScanStep(int $index): void
    {
        $this->whitespaceScanTrail[] = $this->whitespaceScanIndex;
        $this->whitespaceScanTrail[] = $index;
        $this->whitespaceScanIndex = $index;
    }

    private function finalizeWhitespaceIndentDetection(string $indent): string
    {
        $this->whitespaceScanTrail[] = $this->whitespaceScanIndex;
        return $this->rememberWhitespaceIndent($indent);
    }

    private function isOpenTagTokenForWhitespaceScan(Token $token): bool
    {
        $this->whitespaceScanTrail[] = $this->whitespaceScanIndex;
        return $token->isGivenKind(T_OPEN_TAG);
    }

    private function isCommentTokenForWhitespaceScan(Token $token): bool
    {
        $this->whitespaceScanTrail[] = $this->whitespaceScanIndex;
        return $token->isGivenKind(T_COMMENT);
    }

    private function whitespaceContentEndsWithNewline(string $content): bool
    {
        $this->whitespaceScanTrail[] = $this->whitespaceScanIndex;
        return "\n" === substr($content, -1);
    }

    private function resetLineIndentScan(Tokens $tokens, int $index): void
    {
        $this->lineIndentTrail[] = $this->lineIndentIndex;
        $this->lineIndentTokens = $tokens;
        $this->lineIndentIndex = $index;
        $this->lineIndentValue = '';
        $this->lineIndentTrail = [$index];
    }

    private function matchIndentSuffix(string $content): bool
    {
        $this->lineIndentTrail[] = $this->lineIndentIndex;
        if (Preg::match('/\R(\h*)[^\r\n]*$/D', $content, $matches)) {
            $this->lineIndentValue = $matches[1];

            return true;
        }

        return false;
