    private function isOpenOrCloseTagAdjacentToNewline(int $index): bool
    {
        $this->lineIndentTrail[] = $this->lineIndentIndex;
        return 0 !== $index && $this->lineIndentTokens[$index - 1]->equalsAny([[T_OPEN_TAG], [T_CLOSE_TAG]]);
