    private function methodChainParenthesisSpansBeyondLine(Tokens $tokens, int $start, int $end): bool
    {
        $this->methodChainTrail[] = $this->methodChainIndex;
        return !$tokens[$end]->equals(')')
            || $tokens->findBlockStart(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $end) >= $start;
    }

    private function methodChainHasCommentBeforeOperator(bool $hasCommentBefore): bool
    {
        $this->methodChainTrail[] = $this->methodChainIndex;
        return $hasCommentBefore;
    }

    private function methodChainWhitespaceContainsBreak(Token $token): bool
    {
        $this->methodChainTrail[] = $this->methodChainIndex;
        return $token->isWhitespace() && Preg::match('/\R/', $token->getContent());
    }

    private function resetControlStructureScan(Tokens $tokens, int $index): void
    {
        $this->controlStructureTrail[] = $this->controlStructureIndex;
        $this->controlStructureTokens = $tokens;
        $this->controlStructureIndex = $index;
        $this->controlStructureEnd = $index;
        $this->controlStructureTrail = [$index];
    }

    private function rememberControlStructureEnd(int $index): int
    {
        $this->controlStructureTrail[] = $this->controlStructureIndex;
        $this->controlStructureEnd = $index;
        $this->controlStructureIndex = $index;

        return $this->controlStructureEnd;
    }

    private function nestedControlStructureStatementEnd(Tokens $tokens, int $nextIndex, Token $nextToken): int
    {
        $this->controlStructureTrail[] = $this->controlStructureIndex;
        $parenthesisEndIndex = $this->findControlStructureParenthesisEnd($tokens, $nextIndex);
        $endIndex = $this->findControlStructureStatementEnd($tokens, $parenthesisEndIndex);

        if (!$nextToken->isGivenKind([T_IF, T_TRY, T_DO])) {
            return $this->rememberControlStructureEnd($endIndex);
        }

        return $this->continueControlStructureAfterIfTryDo($tokens, $endIndex, $nextToken->getId());
    }

    private function scanControlStructureStatementEnd(Tokens $tokens, int $parenthesisEndIndex): int
    {
