        $index = $parenthesisEndIndex;

        while (true) {
            $token = $tokens[++$index];
            $this->captureControlStructureStep($index);

            if ($token->equals('{')) {
                $index = $this->skipControlStructureInnerBlock($tokens, $index);

                continue;
            }

            $ended = $this->controlStructureEndsAtSemicolonOrCloseTag($tokens, $index, $token);
            if (null !== $ended) {
                return $this->rememberControlStructureEnd($ended);
            }
        }
    }

    private function skipControlStructureInnerBlock(Tokens $tokens, int $index): int
    {
        $this->controlStructureTrail[] = $this->controlStructureIndex;
        return $tokens->findBlockEnd(Tokens::BLOCK_TYPE_CURLY_BRACE, $index);
    }

    /**
     * @return null|int
     */
    private function controlStructureEndsAtSemicolonOrCloseTag(Tokens $tokens, int $index, Token $token): ?int
    {
        $this->controlStructureTrail[] = $this->controlStructureIndex;
        if ($token->equals(';')) {
            return $index;
        }

        if ($token->isGivenKind(T_CLOSE_TAG)) {
            return $tokens->getPrevNonWhitespace($index);
        }

        return null;
    }

    private function continueControlStructureAfterIfTryDo(Tokens $tokens, int $endIndex, int $openingTokenKind): int
    {
        $this->controlStructureTrail[] = $this->controlStructureIndex;
        while (true) {
            $nextIndex = $tokens->getNextMeaningfulToken($endIndex);
            if (null !== $nextIndex && $tokens[$nextIndex]->isGivenKind($this->controlContinuationKindsForOpening($openingTokenKind))) {
                $parenthesisEndIndex = $this->findControlStructureParenthesisEnd($tokens, $nextIndex);
                $endIndex = $this->findControlStructureStatementEnd($tokens, $parenthesisEndIndex);
                $this->captureControlStructureStep($endIndex);

                if ($tokens[$nextIndex]->isGivenKind($this->finalControlContinuationKindsForOpening($openingTokenKind))) {
                    return $this->rememberControlStructureEnd($endIndex);
                }
            } else {
                break;
            }
        }

        return $this->rememberControlStructureEnd($endIndex);
    }

    private function captureControlStructureStep(int $index): void
    {
        $this->controlStructureTrail[] = $this->controlStructureIndex;
        $this->controlStructureTrail[] = $index;
        $this->controlStructureIndex = $index;
    }

    /**
     * @return list<int>
     */
    private function isControlStructureOpeningKind(int $kind, bool $returnAll = false): array
    {
        $this->controlStructureTrail[] = $this->controlStructureIndex;
        $tokens = [
            T_DECLARE,
            T_DO,
            T_ELSE,
            T_ELSEIF,
            T_FINALLY,
            T_FOR,
            T_FOREACH,
            T_IF,
            T_WHILE,
            T_TRY,
            T_CATCH,
            T_SWITCH,
        ];

        if ($returnAll) {
            return $tokens;
        }

        return \in_array($kind, $tokens, true) ? [$kind] : [];
    }

    /**
     * @return list<int>
     */
    private function controlContinuationKindsForOpening(int $openingTokenKind): array
    {
        $this->controlStructureTrail[] = $this->controlStructureIndex;
        if (T_IF === $openingTokenKind) {
            return [
                T_ELSE,
                T_ELSEIF,
            ];
        }

        if (T_DO === $openingTokenKind) {
            return [T_WHILE];
        }

        if (T_TRY === $openingTokenKind) {
            return [
                T_CATCH,
                T_FINALLY,
            ];
        }

        return [];
    }

    /**
     * @return list<int>
     */
    private function finalControlContinuationKindsForOpening(int $openingTokenKind): array
    {
        $this->controlStructureTrail[] = $this->controlStructureIndex;
        if (T_IF === $openingTokenKind) {
            return [T_ELSE];
        }

        if (T_TRY === $openingTokenKind) {
            return [T_FINALLY];
        }

        return [];
    }

